-- Isolated SAMPLE references, commercial pins and physical packing; every row rolls back.
begin;
select set_config('app.sample_company_id',gen_random_uuid()::text,true);
select set_config('app.sample_operator_id',gen_random_uuid()::text,true);
select set_config('app.sample_reader_id',gen_random_uuid()::text,true);
select set_config('app.sample_outsider_id',gen_random_uuid()::text,true);
insert into auth.users(id,aud,role,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
 select current_setting(setting)::uuid,'authenticated','authenticated','sample+'||current_setting(setting)||'@invalid.test',now(),'{"provider":"email","providers":["email"]}'::jsonb,'{"display_name":"SAMPLE Operator"}'::jsonb,now(),now()
 from unnest(array['app.sample_operator_id','app.sample_reader_id','app.sample_outsider_id']) setting;
insert into public.companies(id,name,created_by) values(current_setting('app.sample_company_id')::uuid,'SAMPLE Customer Parts Factory',current_setting('app.sample_operator_id')::uuid);
insert into public.plants(company_id,name) values(current_setting('app.sample_company_id')::uuid,'SAMPLE Plant');
insert into public.company_memberships(company_id,user_id) select current_setting('app.sample_company_id')::uuid,current_setting(setting)::uuid from unnest(array['app.sample_operator_id','app.sample_reader_id']) setting;
insert into public.user_company_roles(company_id,user_id,role) values(current_setting('app.sample_company_id')::uuid,current_setting('app.sample_operator_id')::uuid,'admin'),(current_setting('app.sample_company_id')::uuid,current_setting('app.sample_reader_id')::uuid,'planning');
set local role authenticated;
select set_config('request.jwt.claim.sub',current_setting('app.sample_operator_id'),true);
do $$
declare c uuid:=current_setting('app.sample_company_id')::uuid;cust uuid;othercust uuid;item uuid;raw uuid;centre uuid;wh uuid;loc uuid;part uuid;replacement uuid;otherpart uuid;payload jsonb;
 rfq uuid;draft uuid;approved uuid;so uuid;line uuid;pkg uuid;wo uuid;lot uuid;plan uuid;res uuid;shipment uuid;result jsonb;
begin
 insert into public.customers(company_id,code,name) values(c,'SAMPLE-C1','SAMPLE Customer One') returning id into cust;
 insert into public.customers(company_id,code,name) values(c,'SAMPLE-C2','SAMPLE Customer Two') returning id into othercust;
 insert into public.items(company_id,sku,description,base_uom) values(c,'SAMPLE-OUT','SAMPLE Output','pcs') returning id into item;
 insert into public.items(company_id,sku,description,base_uom) values(c,'SAMPLE-RAW','SAMPLE Input','pcs') returning id into raw;
 insert into public.work_centres(company_id,plant_id,code,name) select c,id,'SAMPLE-WC','SAMPLE Work Centre' from public.plants where company_id=c returning id into centre;
 insert into public.warehouses(company_id,plant_id,code,name) select c,id,'SAMPLE-WH','SAMPLE Warehouse' from public.plants where company_id=c returning id into wh;
 insert into public.stock_locations(company_id,warehouse_id,code,name) values(c,wh,'SAMPLE-LOC','SAMPLE Location') returning id into loc;
 payload:=jsonb_build_object('customer_id',cust,'item_id',item,'part_number','sample-pn','part_revision','a','description','SAMPLE original customer description','drawing_revision_id',null,'reason','SAMPLE checked customer specification');
 part:=public.create_customer_part_reference(c,payload,'part');
 if public.create_customer_part_reference(c,payload,'part')<>part then raise exception 'SAMPLE_PART_RETRY_CHANGED';end if;
 if not exists(select 1 from public.customer_item_references where id=part and part_number='SAMPLE-PN' and part_revision='A' and reference_version=1) then raise exception 'SAMPLE_PART_NORMALIZATION';end if;
 begin perform public.create_customer_part_reference(c,jsonb_set(payload,'{description}','"SAMPLE different"'),'part');raise exception 'SAMPLE_PART_KEY_REUSED';exception when others then if sqlerrm<>'IDEMPOTENCY_CONFLICT' then raise;end if;end;
 begin perform public.create_customer_part_reference(c,payload,'duplicate');raise exception 'SAMPLE_DUPLICATE_ACTIVE_MAPPING';exception when others then if sqlerrm<>'CUSTOMER_PART_ACTIVE_EXISTS' then raise;end if;end;
 begin perform public.create_customer_part_reference(c,jsonb_set(payload,'{customer_id}',to_jsonb(gen_random_uuid())),'wrong-customer');raise exception 'SAMPLE_FOREIGN_CUSTOMER';exception when others then if sqlerrm<>'CUSTOMER_NOT_FOUND' then raise;end if;end;
 begin perform public.create_customer_part_reference(c,jsonb_set(payload,'{drawing_revision_id}',to_jsonb(gen_random_uuid())),'wrong-drawing');raise exception 'SAMPLE_FOREIGN_DRAWING';exception when others then if sqlerrm<>'ENGINEERING_REVISION_ITEM_MISMATCH' then raise;end if;end;
 otherpart:=public.create_customer_part_reference(c,jsonb_set(jsonb_set(payload,'{customer_id}',to_jsonb(othercust)),'{part_revision}','""'),'unversioned');
 if not exists(select 1 from public.customer_item_references where id=otherpart and part_revision='') then raise exception 'SAMPLE_INVENTED_CUSTOMER_REVISION';end if;
 rfq:=public.create_rfq(c,'SAMPLE-RFQ',cust,'SAMPLE parts enquiry',jsonb_build_array(jsonb_build_object('item_id',item,'requested_description','SAMPLE fastener','quantity','2','uom','pcs')),'rfq');
 perform public.record_feasibility(c,rfq,'feasible',null,null,null,'SAMPLE stock/production supply',1,'feasible');
 begin perform public.create_quotation(c,rfq,'SAMPLE-FOREIGN-Q','INR',current_date+30,jsonb_build_array(jsonb_build_object('item_id',item,'quantity','2','uom','pcs','unit_price','1','customer_part_reference_id',otherpart)),'wrong-reference');raise exception 'SAMPLE_WRONG_CUSTOMER_QUOTED';exception when others then if sqlerrm<>'CUSTOMER_PART_CONTEXT_MISMATCH' then raise;end if;end;
 begin perform public.create_quotation(c,rfq,'SAMPLE-FOREIGN-ITEM-Q','INR',current_date+30,jsonb_build_array(jsonb_build_object('item_id',raw,'quantity','2','uom','pcs','unit_price','1','customer_part_reference_id',part)),'wrong-item');raise exception 'SAMPLE_WRONG_ITEM_QUOTED';exception when others then if sqlerrm<>'CUSTOMER_PART_CONTEXT_MISMATCH' then raise;end if;end;
 payload:=jsonb_build_array(jsonb_build_object('item_id',item,'quantity','2','uom','pcs','unit_price','1','customer_part_reference_id',part));
 draft:=public.create_quotation(c,rfq,'SAMPLE-DRAFT-Q','INR',current_date+30,payload,'draft');
 if public.create_quotation(c,rfq,'SAMPLE-DRAFT-Q','INR',current_date+30,payload,'draft')<>draft then raise exception 'SAMPLE_QUOTE_RETRY_CHANGED';end if;
 begin perform public.create_quotation(c,rfq,'SAMPLE-DRAFT-Q','INR',current_date+30,jsonb_set(payload,'{0,quantity}','"1"'),'draft');raise exception 'SAMPLE_QUOTE_KEY_CONTENT_CHANGED';exception when others then if sqlerrm<>'IDEMPOTENCY_CONFLICT' then raise;end if;end;
 approved:=public.create_quotation(c,rfq,'SAMPLE-APPROVED-Q','INR',current_date+30,payload,'approved');
 perform public.approve_quotation(c,approved,1,'approve');
 perform public.retire_customer_part_reference(c,part,'SAMPLE reviewed mapping correction','retire');
 if public.retire_customer_part_reference(c,part,'SAMPLE reviewed mapping correction','retire')<>part then raise exception 'SAMPLE_RETIRE_RETRY_CHANGED';end if;
 begin perform public.create_quotation(c,rfq,'SAMPLE-RETIRED-Q','INR',current_date+30,payload,'retired-q');raise exception 'SAMPLE_RETIRED_QUOTE_ALLOWED';exception when others then if sqlerrm<>'CUSTOMER_PART_RETIRED' then raise;end if;end;
 begin perform public.approve_quotation(c,draft,1,'retired-approve');raise exception 'SAMPLE_RETIRED_DRAFT_APPROVED';exception when others then if sqlerrm<>'CUSTOMER_PART_RETIRED' then raise;end if;end;
 replacement:=public.create_customer_part_reference(c,jsonb_build_object('customer_id',cust,'item_id',item,'part_number','SAMPLE-PN','part_revision','A','description','SAMPLE corrected mapping','drawing_revision_id',null,'reason','SAMPLE approved correction'),'replacement');
 if not exists(select 1 from public.customer_item_references where id=replacement and reference_version=2 and retired_at is null) then raise exception 'SAMPLE_MAPPING_VERSION_NOT_ADVANCED';end if;
 so:=public.accept_quotation_create_sales_order(c,approved,'SAMPLE-SO','SAMPLE-PO',current_date+14,2,'accept');
 select id into line from public.sales_order_lines where sales_order_id=so;
 if (select customer_part_reference_id from public.sales_order_lines where id=line) is distinct from part then raise exception 'SAMPLE_ORDER_MAPPING_REBOUND';end if;
 pkg:=public.production_command(c,'create_package',jsonb_build_object('item_id',item,'revision_label','SAMPLE A','basis_quantity','1','components',jsonb_build_array(jsonb_build_object('item_id',raw,'quantity','1','uom','pcs','scrap_allowance_pct','0')),'operations',jsonb_build_array(jsonb_build_object('sequence',10,'work_centre_id',centre,'name','SAMPLE operation'))),'pkg');
 perform public.production_command(c,'approve_package',jsonb_build_object('package_id',pkg),'pkg-approve');
 wo:=public.production_command(c,'create_work_order',jsonb_build_object('sales_order_line_id',line,'package_id',pkg,'number','SAMPLE-WO','quantity','1','start_date',current_date::text,'due_date',(current_date+1)::text),'wo');
 if (select customer_part_reference_id from public.work_orders where id=wo) is distinct from part then raise exception 'SAMPLE_WORK_MAPPING_REBOUND';end if;
 result:=public.get_production_workspace(c);
 if not exists(select 1 from jsonb_array_elements(result->'works') w where (w->>'id')::uuid=wo and w->>'customer_part_number'='SAMPLE-PN' and w->>'customer_part_revision'='A') then raise exception 'SAMPLE_PRODUCTION_REFERENCE_MISSING';end if;
 lot:=public.receive_finished_goods(c,item,loc,'SAMPLE-FINISHED',1,'pcs','receive');
 plan:=public.quality_command(c,'create_plan',jsonb_build_object('item_id',item,'label','SAMPLE Incoming','version','A','sample_size',1,'characteristics','[{"key":"condition","label":"SAMPLE condition","type":"attribute","expected":"PASS"}]'::jsonb),'plan');
 perform public.quality_command(c,'approve_plan',jsonb_build_object('plan_id',plan),'plan-ok');
 perform public.quality_command(c,'inspect',jsonb_build_object('plan_id',plan,'lot_id',lot,'kind','incoming','revision',1,'readings','[{"key":"condition","values":["PASS"]}]'::jsonb,'reason','SAMPLE checked'),'inspect');
 perform public.release_stock_lot(c,lot,1,'release');
 res:=public.reserve_finished_goods(c,line,lot,1,1,'reserve');
 shipment:=public.prepare_packing_shipment(c,so,'SAMPLE-PACK','SAMPLE-SHIP',jsonb_build_array(jsonb_build_object('reservation_id',res,'quantity','1')),2,'packing');
 result:=public.get_packing_workspace(c);
 if not exists(select 1 from jsonb_array_elements(result->'lines') l where (l->>'shipment_id')::uuid=shipment and l->>'customer_part_number'='SAMPLE-PN' and l->>'customer_part_revision'='A') then raise exception 'SAMPLE_PACKAGE_REFERENCE_MISSING';end if;
 perform set_config('app.sample_part_id',part::text,true);
 perform set_config('request.jwt.claim.sub',current_setting('app.sample_reader_id'),true);
 if jsonb_array_length(public.get_customer_part_workspace(c))<>3 then raise exception 'SAMPLE_REFERENCE_HISTORY_MISSING';end if;
 begin perform public.retire_customer_part_reference(c,replacement,'SAMPLE denied','reader-retire');raise exception 'SAMPLE_READER_WRITE_ALLOWED';exception when others then if sqlerrm<>'FORBIDDEN' then raise;end if;end;
 begin update public.customer_item_references set description='SAMPLE forged' where id=replacement;raise exception 'SAMPLE_DIRECT_REFERENCE_WRITE';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',current_setting('app.sample_outsider_id'),true);
 if exists(select 1 from public.customer_item_references where company_id=c) then raise exception 'SAMPLE_CUSTOMER_PART_TENANT_LEAK';end if;
 begin perform public.get_customer_part_workspace(c);raise exception 'SAMPLE_CUSTOMER_PART_WORKSPACE_LEAK';exception when others then if sqlerrm<>'FORBIDDEN' then raise;end if;end;
end $$;
reset role;
do $$ begin
 begin update public.customer_item_references set part_number='SAMPLE-FORGED' where id=current_setting('app.sample_part_id')::uuid;raise exception 'SAMPLE_MAPPING_HISTORY_MUTABLE';exception when others then if sqlerrm<>'CUSTOMER_PART_IMMUTABLE' then raise;end if;end;
 begin delete from public.customer_item_references where id=current_setting('app.sample_part_id')::uuid;raise exception 'SAMPLE_MAPPING_HISTORY_DELETED';exception when others then if sqlerrm<>'CUSTOMER_PART_IMMUTABLE' then raise;end if;end;
end $$;
rollback;
